// THROWAWAY: one route, three rendering variants, synthetic in-memory adapters.
// Command completion inserts ordinary message text; it never sends or executes a command.
const $=s=>document.querySelector(s), esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const variants={A:['现有结构减负','保留双栏时间轴；对话集中；任务保留说明'],B:['Agenda 优先','宽泛安排先读；列表加详情；两栏对话'],C:['时间轴工作台','拖动与选区；任务按日期分组；三栏对话']};
const pages={today:'今天',tasks:'任务',calendar:'日历',collaboration:'协作'};
const baseline=[{id:'p1',band:'上午',name:'启动与聚焦',note:'早餐后处理一件重要的事；时间可以弹性调整。'},{id:'p2',band:'午后',name:'整理本周安排',note:'先盘点已有事项，再决定今天推进哪一件。'},{id:'p3',band:'晚间',name:'吃饭、休息与收尾',note:'给晚饭、活动和睡前回顾留出空间。'}];
const initialTasks=[{id:'t1',name:'回复项目邮件',note:'整理三个问题，再发出一封简短回复。',time:600,duration:45,list:'Inbox',date:'2026-10-10',done:false},{id:'t2',name:'整理本周待办与下周安排',note:'只做一次小范围盘点，分出本周、以后与等待回复。',time:900,duration:45,list:'Inbox',date:'2026-10-10',done:false},{id:'t3',name:'买菜',note:'蔬菜、水果和牛奶。',time:null,duration:30,list:'Inbox',date:'2026-10-10',done:false},{id:'t4',name:'预约下一次牙齿清洁',note:'先确认合适的日期和诊所。',time:null,duration:30,list:'Inbox',date:null,done:false},{id:'t5',name:'看完收藏的设计分享视频',note:'看完后记下一个想试的小技巧。',time:null,duration:45,list:'以后想做',date:null,done:false},{id:'t6',name:'整理桌面',note:'已经记录完成；没有精确完成时间。',time:null,duration:30,list:'Inbox',date:'2026-10-10',done:true}];
const facts=[{id:'f1',name:'已阅读 25 分钟',time:550,note:'已明确报告的事实；原型中不因移动时间自动变化。'},{id:'f2',name:'桌面整理完成',time:null,note:'发生时刻没有记录。'}];
let params=new URLSearchParams(location.search),variant=variants[params.get('variant')]?params.get('variant'):'A',page=pages[params.get('page')]?params.get('page'):'today',phase='daytime',tasks=structuredClone(initialTasks),plans=structuredClone(baseline),selectedTask='t2',scope='all',draft='',commandDismissed=false,showContext=variant==='C',showSessions=false,emptyChat=false,calendarLines=4,lastAction='等待操作',selection=null,dragged=null;
let messages=[{role:'user',text:'我今天下午想先整理一下安排，晚上留点时间休息。'},{role:'assistant',text:'可以。午后先留给整理安排，晚上保持弹性。已经保留早间基准，当前安排仍然只有宽泛时间，没有设定具体分钟。',history:true}];
const time=m=>m==null?'未设时间':`${String(Math.floor(m/60)).padStart(2,'0')}:${String(m%60).padStart(2,'0')}`;
const taskById=id=>tasks.find(t=>t.id===id),bandOf=m=>m<720?'上午':m<1080?'午后':'晚间';
const btn=(text,action,cls='')=>`<button class="btn ${cls}" data-action="${action}">${text}</button>`;
function notify(text){lastAction=text;$('#toast').textContent=text;$('#toast').style.opacity=1;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').style.opacity=0,2400)}
function header(title,description,actions=''){return `<header class="page-head"><div><h1>${title}</h1><p>${description}</p></div><div class="head-actions">${actions}</div></header>`}
function phaseTabs(){return `<div class="phase-tabs">${[['morning','早晨计划'],['daytime','白天安排'],['evening','晚间复盘']].map(([key,label])=>`<button data-phase="${key}" class="${phase===key?'active':''}">${label}</button>`).join('')}</div>`}
function taskRow(t,verbose=false){return `<div class="task-row ${t.done?'done':''}"><input type="checkbox" data-complete="${t.id}" aria-label="完成 ${esc(t.name)}" ${t.done?'checked':''}><div class="task-body"><button class="task-name" data-task="${t.id}">${esc(t.name)}</button>${verbose?`<p>${esc(t.note)}</p><span class="tiny muted">${esc(t.list)} · ${t.date||'未排期'}</span>`:''}</div><span class="date-chip">${t.time==null?(t.date?'今天':'未排期'):time(t.time)}</span>${verbose?`<div class="row-actions"><button class="text-button" data-task="${t.id}">详情</button><button class="text-button" data-discuss="${t.id}">讨论</button></div>`:`<button class="text-button" data-task="${t.id}" aria-label="更多操作 ${esc(t.name)}">···</button>`}</div>`}
function taskSummary(){return `<section class="surface"><div class="section-title"><h2>今天的任务</h2><span class="muted tiny">${tasks.filter(t=>t.date==='2026-10-10'&&!t.done).length} 待办</span></div>${tasks.filter(t=>t.date==='2026-10-10'&&!t.done).map(t=>taskRow(t)).join('')}${btn('查看全部任务','tasks')}<div class="fact-note"><span class="pill fact">已记录</span><p>桌面整理完成，发生时刻未记录。</p></div></section>`}
function timeline(){const bands=[['上午',480,720],['午后',720,1080],['晚间',1080,1200]];return `<div class="timeline-head"><span></span><b>当前安排</b><b>精确任务 / 已记录事实</b></div><div class="timeline-scroll"><div class="timeline" data-timeline tabindex="0" aria-label="精确任务时间轴；拖动任务或在空白处选取时间段">${Array.from({length:13},(_,i)=>`<span class="time-tick" style="top:${i*72}px">${String(i+8).padStart(2,'0')}:00</span>`).join('')}<div class="divider"></div>${bands.map(([band,start,end])=>`<div data-band="${band}" style="position:absolute;left:0;width:49%;top:${(start-480)*1.2}px;height:${(end-start)*1.2}px"></div>`).join('')}${plans.map(p=>{const b=bands.find(b=>b[0]===p.band);const same=plans.filter(x=>x.band===p.band),offset=same.indexOf(p);return `<button class="coarse" draggable="true" data-plan="${p.id}" style="top:${(b[1]-480)*1.2+10+offset*105}px;height:${Math.min(130,(b[2]-b[1])*1.2-20)}px"><div><span>${p.band} · 具体时刻未定</span><b>${esc(p.name)}</b><p class="tiny">${esc(p.note)}</p></div></button>`}).join('')}${tasks.filter(t=>t.date==='2026-10-10'&&t.time!=null&&!t.done).map(t=>`<button class="timed-task" draggable="true" data-task="${t.id}" data-drag-task="${t.id}" style="top:${(t.time-480)*1.2}px;height:${t.duration*1.2}px"><div><span>${time(t.time)} · Task</span><b>${esc(t.name)}</b></div></button>`).join('')}${facts.filter(f=>f.time!=null).map(f=>`<div class="actual-fact" style="top:${(f.time-480)*1.2}px;height:48px"><span class="pill fact">已记录</span> ${time(f.time)}<br>${esc(f.name)}</div>`).join('')}<div class="now-line"><span>14:15</span></div><div class="selection-ghost hidden"></div></div></div>`}
function today(){let content='';if(phase==='evening')return header('今天','2026 年 10 月 10 日 · 周六')+phaseTabs()+evening();if(phase==='morning')content=`<section class="surface"><div class="section-title"><h2>早晨的原始安排</h2><span class="pill">基准保留</span></div>${baseline.map(p=>`<div class="agenda-band"><h2>${p.band}</h2><div><b>${esc(p.name)}</b><p class="muted content-copy">${esc(p.note)}</p></div></div>`).join('')}<p class="help-note">白天移动任务或调整当前安排，不改变这一份基准。</p></section>`;
else if(variant==='A')content=`<div class="two-col"><section class="surface"><div class="section-title"><h2>一天的安排与记录</h2><span class="tiny muted">宽泛安排 + 精确任务</span></div><p class="help-note">宽泛安排占据上午、午后、晚间区段，未设定精确起止。拖动右侧任务调整时间；在空白处拖出一个新时间段。</p>${timeline()}</section>${taskSummary()}</div>`;
else if(variant==='B')content=`<div class="day-strip"><b>接下来</b><span>午后整理安排，晚上保留吃饭与休息的空间。</span>${btn('调整计划','collaboration')}</div><div class="two-col"><section class="agenda">${['上午','午后','晚间'].map(b=>`<section class="agenda-band"><h2>${b}</h2><div><div class="muted">宽泛安排 · 未指定分钟</div>${plans.filter(p=>p.band===b).map(p=>`<div class="agenda-plan"><span class="pill plan">安排</span><b>${esc(p.name)}</b><p class="muted tiny content-copy">${esc(p.note)}</p></div>`).join('')}${tasks.filter(t=>t.date==='2026-10-10'&&t.time!=null&&bandOf(t.time)===b&&!t.done).map(t=>`<div class="agenda-task"><input type="checkbox" data-complete="${t.id}" aria-label="完成 ${esc(t.name)}"><span class="time-label">${time(t.time)}</span><button data-task="${t.id}">${esc(t.name)}</button></div>`).join('')}${b==='上午'?'<div class="fact-note">已记录：09:10 阅读了 25 分钟。</div>':''}</div></section>`).join('')}<div style="padding:16px 0"><details><summary>需要精确排时间时，打开时间轴</summary><div style="margin-top:20px">${timeline()}</div></details></div></section>${taskSummary()}</div>`;
else content=`<div class="workspace-timeline"><section class="surface"><div class="section-title"><h2>安排工作台</h2><div class="inline-actions"><span class="pill plan">宽泛安排</span><span class="pill task">Task</span><span class="pill fact">事实</span></div></div><p class="help-note">拖动 Task 改时间，空白选区新建。宽泛计划只能移动到另一时间区段；事实保持原记录。</p>${timeline()}</section><aside class="surface"><div class="section-title"><h2>待安排</h2><span class="muted tiny">可拖入</span></div><div class="scheduled-list">${tasks.filter(t=>t.time==null&&!t.done).map(t=>`<div class="unscheduled" draggable="true" data-drag-task="${t.id}"><b>${esc(t.name)}</b><p class="tiny muted">${t.date?'今天 · 时间未定':'未排期'} ↗</p>${btn('设定时间','schedule:'+t.id)}</div>`).join('')}</div><div class="fact-note"><b>已记录事实</b><p>桌面已整理。时刻未知。</p></div><details class="help-note"><summary>查看早间基准</summary>${baseline.map(p=>`<p>${p.band}：${esc(p.name)}</p>`).join('')}</details></aside></div>`;
return header('今天','2026 年 10 月 10 日 · 周六',btn('晚间复盘','evening')+btn('与 Codex 讨论','collaboration','primary'))+phaseTabs()+content}
function evening(){return `<section class="surface evening"><span class="pill">晚间复盘</span><h2>回看今天，再轻轻收尾</h2><div class="evening-intro">可以从已经记录的事情开始。不必重建完整的一天，也不用补齐所有空白。</div><div class="review-facts"><div class="soft-surface"><h3>当前安排</h3><ul>${plans.map(p=>`<li>${p.band} · ${esc(p.name)}</li>`).join('')}</ul></div><div class="soft-surface"><h3>已经记录</h3><ul><li>阅读了 25 分钟</li><li>桌面整理完成</li><li>其他活动仍未记录</li></ul></div></div>${btn('开始今晚复盘','start-evening','primary')}<p class="help-note">进入协作，并带上 10 月 10 日的记录背景。你仍可以编辑消息后发送。</p></section>`}
function scopeControls(){return `<div class="list-scope">${[['all','全部'],['today','今天'],['inbox','Inbox'],['later','以后想做']].map(([key,label])=>`<button class="btn ${scope===key?'active':''}" data-scope="${key}">${label}</button>`).join('')}</div>`}
function filteredTasks(){return tasks.filter(t=>scope==='all'||scope==='today'&&t.date==='2026-10-10'||scope==='inbox'&&t.list==='Inbox'||scope==='later'&&t.list==='以后想做')}
function quickAdd(){return `<form class="quick-add" data-quick-form><input name="name" aria-label="快速添加任务" placeholder="＋ 添加一个任务，Enter 确认" required><button class="btn primary">添加</button></form>`}
function taskDetail(t){return `<aside class="detail-panel"><div class="section-title"><span class="pill">任务详情</span><button class="text-button" data-action="close-task">关闭</button></div><h2>${esc(t.name)}</h2><p class="content-copy muted">${esc(t.note)}</p><label>日期</label><input type="date" value="${t.date||''}" data-edit-date="${t.id}"><label>时间</label><input type="time" value="${t.time==null?'':time(t.time)}" data-edit-time="${t.id}"><label>列表</label><select data-edit-list="${t.id}"><option ${t.list==='Inbox'?'selected':''}>Inbox</option><option ${t.list==='以后想做'?'selected':''}>以后想做</option></select><div class="inline-actions" style="margin-top:20px">${btn('与 Codex 讨论','discuss:'+t.id)}${btn(t.done?'重新打开':'标为完成','complete:'+t.id)}</div></aside>`}
function taskPage(){let list=filteredTasks();let content=variant==='A'?`<section class="surface">${quickAdd()}${list.map(t=>taskRow(t,true)).join('')}</section>`:variant==='B'?`<section class="surface task-list-detail"><div>${quickAdd()}${list.map(t=>taskRow(t)).join('')}</div>${selectedTask?taskDetail(taskById(selectedTask)): '<aside class="detail-panel muted">选择一个任务查看详情</aside>'}</section>`:`${quickAdd()}<div class="kanban">${[['今天',list.filter(t=>t.date==='2026-10-10'&&!t.done)],['未排期',list.filter(t=>!t.date&&!t.done)],['已完成',list.filter(t=>t.done)]].map(([name,items])=>`<section class="kanban-col"><h2>${name} · ${items.length}</h2>${items.map(t=>taskRow(t,true)).join('')}</section>`).join('')}</div>`;return header('任务','任务、今天和日历使用同一份演示 Task',btn('新任务','new-task','primary'))+scopeControls()+content}
function sessions(){return `<aside class="sessions"><h2>会话</h2>${btn('＋ 新对话','new-chat')}<button class="session active" data-action="select-chat">今天的安排<small>10 月 10 日 · 示例</small></button><button class="session" data-action="sample-retro">最近一周复盘<small>10 月 3–9 日 · 示例</small></button></aside>`}
function contextPanel(){return `<aside class="chat-context"><h2>当前背景</h2><p><b>目标日期</b><br>2026 年 10 月 10 日</p><hr><p><b>当前安排</b></p>${plans.map(p=>`<p>${p.band} · ${esc(p.name)}</p>`).join('')}<hr><p><b>Task</b><br>${tasks.filter(t=>!t.done).length} 项待办</p><p><b>最近记录</b><br>阅读 25 分钟，桌面已整理。</p><p class="muted">可按需查看，不要求每轮把所有背景铺开。</p></aside>`}
function messageMarkup(m){if(m.retro)return `<article class="message"><span class="role">Codex · 示例回复</span><h3>最近一周复盘</h3><p>计划与实际分开看。记录不足的日期保持未知。</p><ul><li>工作与学习有明确推进记录。</li><li>有些事项需要继续安排，未完成并不等于失败。</li></ul><p>小建议：下一周只选择一项安排作调整。</p><button class="source-link" data-action="today">查看当日记录</button>${historyMarkup()}</article>`;return `<article class="message ${m.role}"><span class="role">${m.role==='user'?'你':'Codex · 示例回复'}</span>${esc(m.text).replace(/\n/g,'<br>')}${m.history?historyMarkup():''}</article>`}
function historyMarkup(){return `<details class="work-history"><summary>工作历史 · 3 次读取 · 未修改记录</summary><p>读取 Daily Records · 10 月 3–9 日</p><p>读取 Tasks · 10 月 3–9 日</p><p>读取本地 Habits · 10 月 3–9 日</p></details>`}
function collaboration(){const single=variant==='A';return header('协作','持续对话，按需查看背景',btn('新对话','new-chat')+btn(showContext?'收起背景':'查看背景','context'))+(single?`<div class="session-strip">${btn(showSessions?'收起会话':'会话历史','sessions')}<span class="muted tiny">今天的安排 · 10 月 10 日</span></div>${showSessions?`<div class="session-strip">${btn('今天的安排','select-chat')}${btn('最近一周复盘','sample-retro')}</div>`:''}`:'')+`<div class="chat-layout variant-${variant} ${showContext?'context-open':''}">${single?'':sessions()}<section class="chat-main"><div class="chat-top"><b>${emptyChat?'新对话':'今天的安排'}</b><span class="muted tiny">目标日期 · 10 月 10 日</span></div><div class="messages">${showContext&&variant!=='C'?`<div class="mini-context">${plans.map(p=>`${p.band}：${esc(p.name)}`).join(' · ')}</div>`:''}${emptyChat&&!messages.length?'<div class="empty-chat"><p>从一句话开始</p><small>输入 / 查看可用命令，或直接描述你想讨论的事。</small></div>':messages.map(messageMarkup).join('')}</div><form class="composer" id="composer"><div class="command-menu" role="listbox" aria-label="可用命令" id="command-menu" hidden></div><div class="composer-box"><textarea id="message-draft" aria-label="协作消息" aria-controls="command-menu" aria-expanded="false" placeholder="说说今天的情况，或输入 / 查看命令">${esc(draft)}</textarea><div class="composer-bottom"><small>⌘ Enter 发送</small><button type="button" class="text-button" data-action="dictation" aria-label="听写演示">🎙</button><button class="btn primary" type="submit">发送</button></div></div></form></section>${variant==='C'&&showContext?contextPanel():''}</div>`}
function calendarGrid(mini=false){const sampleFor=n=>tasks.filter(t=>t.date==='2026-10-'+String(n).padStart(2,'0'));return `<div class="week-head">${['日','一','二','三','四','五','六'].map(d=>`<span>${d}</span>`).join('')}</div><div class="calendar-grid">${Array.from({length:35},(_,i)=>{const n=i-3;return `<button class="calendar-day ${n===10?'today':''}" data-day="${n}"><span class="day-number">${n>0&&n<=31?n:'·'}</span>${!mini&&n>0&&n<=31?sampleFor(n).slice(0,calendarLines).map(t=>`<span class="calendar-task">${esc(t.name)}</span>`).join('')+(sampleFor(n).length>calendarLines?`<span class="calendar-more">＋ ${sampleFor(n).length-calendarLines} 项</span>`:''):''}</button>`}).join('')}</div>`}
function calendarPage(){const preview=`<aside class="surface day-preview"><h2>10 月 10 日</h2><p class="muted">${tasks.filter(t=>t.date==='2026-10-10').length} 个 Task · ${facts.length} 条已记录事实</p>${tasks.filter(t=>t.date==='2026-10-10').slice(0,4).map(t=>`<div class="preview-task" data-task="${t.id}">${t.time==null?'时间未定':time(t.time)} · ${esc(t.name)}</div>`).join('')}<div style="margin-top:15px">${btn('打开当天','today')}</div></aside>`;let content=variant==='A'?`<div class="calendar-layout"><section class="surface">${calendarGrid()}</section>${preview}</div>`:variant==='B'?`<section class="surface wide-month">${calendarGrid()}<div class="selected-day-strip"><b>10 月 10 日</b><div class="content-copy">午后：整理本周安排。晚间：吃饭、休息与收尾。<br><span class="muted tiny">详细 Task 和记录另行打开。</span></div>${btn('打开当天','today')}</div></section>`:`<div class="month-agenda"><aside class="surface mini-month">${calendarGrid(true)}</aside><section class="agenda">${[10,11,12].map((n,i)=>`<div class="agenda-band"><h2>${n} 日</h2><div><b>${i===0?'今天 · 当前安排':i===1?'明天 · 尚未安排':'周一 · 示例'}</b>${i===0?tasks.filter(t=>t.date==='2026-10-10').map(t=>taskRow(t)).join(''):'<p class="muted">选择日期查看记录或添加 Task。</p>'}</div></div>`).join('')}</section></div>`;return header('日历','2026 年 10 月 · 同一窗口比较预览密度',btn(calendarLines===4?'切为两行预览':'切为四行预览','calendar-lines'))+content}
function updateUrl(){const u=new URL(location);u.searchParams.set('variant',variant);u.searchParams.set('page',page);history.replaceState(null,'',u)}
function render(){updateUrl();$('.app-shell').dataset.workspaceDestination=page;document.querySelectorAll('[data-page]').forEach(b=>b.setAttribute('aria-current',b.dataset.page===page?'page':'false'));$('#page').innerHTML=page==='today'?today():page==='tasks'?taskPage():page==='calendar'?calendarPage():collaboration();$('#variant-name').textContent=`${variant} · ${variants[variant][0]}`;$('#variant-description').textContent=`${pages[page]} · ${variants[variant][1]}`;bind();if(page==='collaboration')updateCommandMenu()}
function cycle(d){variant=Object.keys(variants)[(Object.keys(variants).indexOf(variant)+d+3)%3];showContext=variant==='C';lastAction=`切换为方案 ${variant}`;render()}
function navigate(next){page=next;render()}
function action(value){if(pages[value])return navigate(value);if(value==='evening'){page='today';phase='evening';render()}else if(value==='start-evening'){draft='请帮我复盘 2026-10-10 的一天。先看当前安排与已经记录的事实，缺少的部分保持未知，先讨论再决定是否保存晚间复盘。';page='collaboration';messages=[];emptyChat=true;commandDismissed=false;render();$('#message-draft').focus();notify('已带入当日背景和可编辑消息，尚未发送')}else if(value==='new-chat'){draft='';messages=[];emptyChat=true;render();$('#message-draft').focus()}else if(value==='select-chat'){emptyChat=false;messages=[{role:'user',text:'下午想先整理安排。'},{role:'assistant',text:'午后留给安排，晚上保持弹性。',history:true}];render()}else if(value==='sample-retro'){emptyChat=false;messages=[{role:'user',text:'/retro'},{role:'assistant',retro:true}];render()}else if(value==='context'){showContext=!showContext;render()}else if(value==='sessions'){showSessions=!showSessions;render()}else if(value==='new-task')openTaskDialog(null,840,870);else if(value==='close-task'){selectedTask=null;render()}else if(value==='calendar-lines'){calendarLines=calendarLines===4?2:4;render()}else if(value==='dictation')notify('这里只演示输入位置，不连接麦克风或转录');else if(value.startsWith('schedule:'))openTaskDialog(taskById(value.slice(9)),840,870);else if(value.startsWith('complete:')){const t=taskById(value.slice(9));t.done=!t.done;render();notify('只改变演示 Task 状态')}else if(value.startsWith('discuss:')){const t=taskById(value.slice(8));draft=`我们讨论一下「${t.name}」的下一步。`;page='collaboration';render();$('#message-draft').focus()}}
function selectTask(id){selectedTask=id;if(page==='tasks'&&variant==='B')render();else openTaskDialog(taskById(id))}
function openTaskDialog(t=null,start=null,end=null){const existing=!!t;const d=$('#detail-dialog');d.innerHTML=`<h2>${existing?'任务详情':'新任务'}</h2><form id="task-dialog-form"><label>名称</label><input name="name" aria-label="任务名称" value="${esc(t?.name||'')}" required placeholder="这一段时间想做什么？"><label>内容</label><textarea name="note">${esc(t?.note||'')}</textarea><div class="two-col" style="grid-template-columns:1fr 1fr"><div><label>日期</label><input name="date" type="date" value="${t?.date||'2026-10-10'}"></div><div><label>时间</label><input name="time" type="time" value="${time(t?.time??start??840)}"></div></div>${end!=null?`<p class="help-note">选中的时间段：${time(start)}–${time(end)}。仅用于体验原型中的排期。</p>`:''}<div class="inline-actions" style="margin-top:20px"><button type="button" class="btn" id="cancel-dialog">取消</button><button class="btn primary">${existing?'保存演示修改':'添加演示任务'}</button>${existing?`<button type="button" class="btn" id="discuss-task">与 Codex 讨论</button>`:''}</div></form>`;d.showModal();$('#cancel-dialog').onclick=()=>d.close();if(existing)$('#discuss-task').onclick=()=>{d.close();action('discuss:'+t.id)};$('#task-dialog-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const value=String(f.get('time'));const minute=value?Number(value.slice(0,2))*60+Number(value.slice(3)):null;if(t){Object.assign(t,{name:String(f.get('name')),note:String(f.get('note')),date:String(f.get('date'))||null,time:minute})}else tasks.push({id:'demo-'+tasks.length,name:String(f.get('name')),note:String(f.get('note')),date:String(f.get('date'))||null,time:minute,duration:end==null?30:Math.max(15,end-start),list:'Inbox',done:false});d.close();render();notify('演示 Task 已改变；真实记录未改动')};}
function bind(){document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelectorAll('[data-phase]').forEach(b=>b.onclick=()=>{phase=b.dataset.phase;render()});document.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>selectTask(b.dataset.task));document.querySelectorAll('[data-discuss]').forEach(b=>b.onclick=()=>action('discuss:'+b.dataset.discuss));document.querySelectorAll('[data-complete]').forEach(c=>c.onchange=()=>{taskById(c.dataset.complete).done=c.checked;render();notify('演示完成状态已更新')});document.querySelectorAll('[data-scope]').forEach(b=>b.onclick=()=>{scope=b.dataset.scope;render()});document.querySelectorAll('[data-quick-form]').forEach(f=>f.onsubmit=e=>{e.preventDefault();tasks.push({id:'demo-'+tasks.length,name:f.elements.name.value,note:'',time:null,duration:30,list:'Inbox',date:null,done:false});render();notify('已加入演示 Inbox；未设置日期')});document.querySelectorAll('[data-edit-date]').forEach(i=>i.onchange=()=>{taskById(i.dataset.editDate).date=i.value||null;render();notify('演示日期已改变')});document.querySelectorAll('[data-edit-time]').forEach(i=>i.onchange=()=>{taskById(i.dataset.editTime).time=i.value?+i.value.slice(0,2)*60+(+i.value.slice(3)):null;render();notify('演示时间已改变')});document.querySelectorAll('[data-edit-list]').forEach(i=>i.onchange=()=>{taskById(i.dataset.editList).list=i.value;render();notify('演示列表已改变')});document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{if(+b.dataset.day>0){const d=$('#detail-dialog');d.innerHTML=`<h2>10 月 ${b.dataset.day} 日</h2><p class="muted">示例日期详情</p>${tasks.filter(t=>t.date==='2026-10-'+String(b.dataset.day).padStart(2,'0')).map(t=>`<p>${time(t.time)} · ${esc(t.name)}</p>`).join('')||'<p class="muted">没有该日的演示任务。</p>'}<button class="btn" id="close-date">关闭</button>`;d.showModal();$('#close-date').onclick=()=>d.close()}});
bindTimeline();const input=$('#message-draft');if(input){input.oninput=()=>{draft=input.value;commandDismissed=false;updateCommandMenu()};input.onkeydown=e=>{if(completionVisible()&&['Enter','Tab','ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();if(['Enter','Tab'].includes(e.key))completeCommand();return}if(e.key==='Escape'&&completionVisible()){e.preventDefault();commandDismissed=true;updateCommandMenu();return}if(e.key==='Enter'&&(e.metaKey||e.ctrlKey)){e.preventDefault();sendMessage()}};$('#composer').onsubmit=e=>{e.preventDefault();sendMessage()}}}
function commandMatch(){const i=$('#message-draft');return !!i&&!commandDismissed&&/^\/[a-z]*$/i.test(i.value.slice(0,i.selectionStart))&&'/retro'.startsWith(i.value.slice(0,i.selectionStart))}
function updateCommandMenu(){const menu=$('#command-menu'),input=$('#message-draft');if(!menu)return;const visible=commandMatch();menu.hidden=!visible;input.setAttribute('aria-expanded',String(visible));menu.innerHTML=visible?`<div class="menu-caption">可用命令</div><button type="button" class="command-option" role="option" aria-selected="true" id="complete-retro"><code>/retro</code><span>个人复盘<small>回看最近 7 个完整生活日，也可以指定日期。</small></span><kbd>Tab ↵</kbd></button>`:'';if(visible)$('#complete-retro').onclick=completeCommand}
function completionVisible(){return $('#command-menu')&&!$('#command-menu').hidden}
function completeCommand(){const i=$('#message-draft');const end=i.selectionStart;draft='/retro '+i.value.slice(end);i.value=draft;i.focus();i.setSelectionRange(7,7);commandDismissed=true;updateCommandMenu();notify('已补全 /retro，尚未发送')}
function sendMessage(){const value=$('#message-draft').value.trim();if(!value)return;messages.push({role:'user',text:value});messages.push(value.startsWith('/retro')?{role:'assistant',retro:true}:{role:'assistant',text:'收到。这是原型里的示例回复；你的输入保留在当前对话中，没有调用模型或写入任何记录。',history:true});draft='';emptyChat=false;render();$('.messages').scrollTop=$('.messages').scrollHeight;notify('已展示示例回复；未运行真实 Codex')}
function bindTimeline(){document.querySelectorAll('[data-drag-task]').forEach(b=>b.ondragstart=e=>{dragged={kind:'task',id:b.dataset.dragTask};e.dataTransfer.setData('text/plain',b.dataset.dragTask)});document.querySelectorAll('[data-plan]').forEach(b=>b.ondragstart=e=>{dragged={kind:'plan',id:b.dataset.plan};e.dataTransfer.setData('text/plain',b.dataset.plan)});document.querySelectorAll('[data-timeline]').forEach(axis=>{const minute=y=>Math.max(480,Math.min(1170,Math.round((y-axis.getBoundingClientRect().top)/1.2/15)*15+480));axis.ondragover=e=>{e.preventDefault();e.dataTransfer.dropEffect='move'};axis.ondrop=e=>{e.preventDefault();if(!dragged)return;const m=minute(e.clientY);if(dragged.kind==='task'){const t=taskById(dragged.id);t.time=m;t.date='2026-10-10';notify(`演示 Task 移到 ${time(m)}；早间基准与事实保持`)}else{const p=plans.find(p=>p.id===dragged.id);p.band=bandOf(m);notify(`当前安排移到${p.band}，仍未设精确时刻`)}dragged=null;render()};axis.onpointerdown=e=>{if(e.target.closest('button')||e.clientX<axis.getBoundingClientRect().left+axis.clientWidth*.51)return;selection={start:minute(e.clientY),end:minute(e.clientY),axis};axis.setPointerCapture(e.pointerId);axis.querySelector('.selection-ghost').classList.remove('hidden')};axis.onpointermove=e=>{if(!selection||selection.axis!==axis)return;selection.end=minute(e.clientY);const ghost=axis.querySelector('.selection-ghost');ghost.style.top=(Math.min(selection.start,selection.end)-480)*1.2+'px';ghost.style.height=Math.max(18,Math.abs(selection.end-selection.start)*1.2)+'px'};axis.onpointerup=e=>{if(!selection||selection.axis!==axis)return;const start=Math.min(selection.start,selection.end),end=Math.max(selection.start,selection.end);selection=null;axis.querySelector('.selection-ghost').classList.add('hidden');if(end-start>=15)openTaskDialog(null,start,end);else notify('在右侧空白时间轴拖出至少 15 分钟，添加任务')};axis.onpointercancel=()=>{selection=null;axis.querySelector('.selection-ghost').classList.add('hidden')}})}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));$('#previous').onclick=()=>cycle(-1);$('#next').onclick=()=>cycle(1);$('#reset').onclick=()=>{tasks=structuredClone(initialTasks);plans=structuredClone(baseline);draft='';messages=[{role:'user',text:'我今天下午想先整理一下安排，晚上留点时间休息。'},{role:'assistant',text:'午后先留给安排，晚上保持弹性。',history:true}];emptyChat=false;selectedTask='t2';lastAction='还原所有内存演示状态';render();notify(lastAction)};$('#inspect').onclick=()=>{const d=$('#state-dialog');d.innerHTML='<h2>原型演示状态</h2><pre></pre><button class="btn">关闭</button>';d.querySelector('pre').textContent=JSON.stringify({variant,page,phase,lastAction,currentArrangement:plans,morningBaseline:baseline,tasks,confirmedFacts:facts,draft,registeredCommandSuggestions:['/retro'],taskDuration:'仅原型模拟时间窗口，现有 Task 的持久时长契约尚未确定',persistence:'none',modelCalls:0},null,2);d.querySelector('button').onclick=()=>d.close();d.showModal()};document.addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select,[contenteditable]')||$('dialog[open]'))return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();cycle(e.key==='ArrowLeft'?-1:1)}});render();
